def main(){
    ps := array(6, 0:Z);

    for i in [0..ps.length) {
        ps[i] = uniformInt(0, 5);
    }
    for i in [0..ps.length) {
        for j in [i+1..ps.length) {
            observe(ps[i] != ps[j]);
        }
